import React from 'react';

const InputBar = ({ value, onChange, onSubmit, isLoading }) => {
  return (
    <form onSubmit={onSubmit} className="flex gap-2">
      <textarea
        value={value}
        onChange={onChange}
        disabled={isLoading}
        placeholder="Send a message..."
        rows={1}
        className="flex-1 resize-none rounded-md border border-gray-300 px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500 dark:bg-gray-700 dark:text-white dark:border-gray-600"
      />
      <button
        type="submit"
        disabled={isLoading}
        className={`px-4 py-2 rounded-md text-white text-sm font-medium ${isLoading ? 'bg-gray-400 cursor-not-allowed' : 'bg-green-500 hover:bg-green-600'}`}
      >
        ➤
      </button>
    </form>
  );
};

export default InputBar;
